def _encode_data_item(item: Any) -> str:
  """Safely encodes data items to string format.

  Args:
    item: The item to encode.

  Returns:
    String representation of the item.
  """
  if hasattr(item, "model_dump"):
    try:
      return item.model_dump(exclude_none=True, by_alias=True)
    except Exception as ex:
      log.warning("Failed to encode data item: %s", ex)
      return str(item)
  return str(item)

