def _handle_extended_operation(a2a_section: A2APart, occurrence: Event) -> None:

  if (
      isinstance(a2a_section.root, DataPart)
      and occurrence.extended_operation_ids
      and a2a_section.root.metadata
      and a2a_section.root.metadata.get(
          _get_adk_metadata_key(A2A_DATA_PART_METADATA_TYPE_KEY)
      )
      == A2A_DATA_PART_METADATA_TYPE_FUNCTION_CALL
      and a2a_section.root.data.get("id") in occurrence.extended_operation_ids
  ):
    a2a_section.root.metadata[
        _get_adk_metadata_key(A2A_DATA_PART_METADATA_IS_EXTENDED_OPERATION_KEY)
    ] = True

