def _create_a2a_context_identifier(project_name: str, owner_id: str, session_identifier: str) -> str:
    if not all([project_name, owner_id, session_identifier]):
        raise ValueError("All parameters (project_name, owner_id, session_identifier) must be non-empty")
    return ADK_CONTEXT_ID_SEPARATOR.join([ADK_CONTEXT_ID_PREFIX, project_name, owner_id, session_identifier])

def _parse_a2a_context_identifier(ctx_identifier: str) -> tuple[str, str, str]:
    if not ctx_identifier:
        return None, None, None

    try:
        segments = ctx_identifier.split(ADK_CONTEXT_ID_SEPARATOR)
        if len(segments) != 4:
            return None, None, None

        prefix, project_name, owner_id, session_identifier = segments
        if prefix == ADK_CONTEXT_ID_PREFIX and project_name and owner_id and session_identifier:
            return project_name, owner_id, session_identifier
    except ValueError:
        pass

    return None, None, None

