def _determine_agent_type(agent_type: str) -> type[BaseAgent]:
    agent_type_name = agent_type or "LlmAgent"
    if "." not in agent_type_name:
        agent_type_name = f"google.adk.agents.{agent_type_name}"

    agent_class = resolve_fully_qualified_name(agent_type_name)
    if inspect.isclass(agent_class) and issubclass(agent_class, BaseAgent):
        return agent_class

    raise ValueError(
