def resolve_fully_qualified_name(fq_name: str) -> Any:
  try:
    module_path, obj_name = fq_name.rsplit(".", 1)
    module = importlib.import_module(module_path)
    return getattr(module, obj_name)
  except Exception as e:
    raise ValueError(f"Invalid fully qualified name: {fq_name}") from e

def _resolve_agent_code_ref(ref: str) -> Any:
    if "." not in ref:
        raise ValueError(f"Invalid code reference: {ref}")

    module_path, obj_name = ref.rsplit(".", 1)
    module = importlib.import_module(module_path)
    obj = getattr(module, obj_name)

    if callable(obj):
        raise ValueError(f"Invalid agent reference to a callable: {ref}")

    if not isinstance(obj, BaseAgent):
        raise ValueError(f"Invalid agent reference to a non-agent instance: {ref}")

    return obj

def determine_code_reference(configuration: CodeConfiguration) -> Any:
    if not configuration or not configuration.name:
        raise ValueError("Invalid CodeConfiguration.")

    module_path, object_name = configuration.name.rsplit(".", 1)
    module = importlib.import_module(module_path)
    instance = getattr(module, object_name)

    if configuration.arguments and callable(instance):
        keyword_arguments = {argument.name: argument.value for argument in configuration.arguments if argument.name}
        positional_arguments = [argument.value for argument in configuration.arguments if not argument.name]

        return instance(*positional_arguments, **keyword_arguments)
    else:
        return instance

