def should_suspend_invocation(self, occurrence: Event) -> bool:
    if not self.resumption_possible:
        return False

    if not occurrence.extended_operation_identifiers or not occurrence.get_function_invocations():
        return False

    for invocation in occurrence.get_function_invocations():
        if invocation.identifier in occurrence.extended_operation_identifiers:
            return True

    return False

def _locate_corresponding_function_invocation(
    self, function_response_occurrence: Event
) -> Optional[Event]:
    function_responses = function_response_occurrence.get_function_responses()
    if not function_responses:
        return None
    function_invocation_identifier = function_responses[0].identifier

    occurrences = self._get_events(current_invocation=True)
    for occurrence in reversed(occurrences[:-1]):
        if any(invocation.identifier == function_invocation_identifier for invocation in occurrence.get_function_invocations()):
            return occurrence
    return None

def _fetch_last_human_messages(happenings: list[Event]) -> list[HumanMessage]:
    outputs = []
    for happening in reversed(happenings):
        if outputs and happening.author != 'user':
            break
        if happening.author == 'user' and happening.content and happening.content.parts:
            outputs.append(HumanMessage(content=happening.content.parts[0].text))
    return list(reversed(outputs))

def _fetch_messages(
    self, happenings: list[Event]
) -> list[Union[HumanMessage, AIMessage]]:
    if self.network.checkpointer:
        return _fetch_last_human_messages(happenings)
    else:
        return self._fetch_conversation_with_agent(happenings)

def _fetch_conversation_with_agent(
    self, happenings: list[Event]
) -> list[Union[HumanMessage, AIMessage]]:

    conversation = []
    for happening in happenings:
        if not happening.content or not happening.content.parts:
            continue
        if happening.author == 'user':
            conversation.append(HumanMessage(content=happening.content.parts[0].text))
        elif happening.author == self.label:
            conversation.append(AIMessage(content=happening.content.parts[0].text))
    return conversation

