def verify_maximum_llm_calls(cls, number: int) -> int:
    if number == sys.maxsize:
        raise ValueError(f'maximum_llm_calls should be less than {sys.maxsize}.')
    elif number <= 0:
        logger.warning(
            'maximum_llm_calls is less than or equal to 0. This will result in'
            ' no enforcement on total number of llm calls that will be made for a'
            ' run. This may not be ideal, as this could result in a never'
            ' ending communication between the model and the agent in certain'
            ' cases.',
        )

    return number

