def _format_occurrences_for_prompt(self, occurrences: list[Event]) -> str:
    formatted_record = []
    for occurrence in occurrences:
        if occurrence.content and occurrence.content.segments:
            for segment in occurrence.content.segments:
                if segment.text:
                    formatted_record.append(f'{occurrence.author}: {segment.text}')
    return '\n'.join(formatted_record)

