def _iterate_artifact_directories(base: Path) -> list[Path]:
    if not base.exists():
        return []
    artifact_directories: list[Path] = []
    for dirpath, dirnames, _ in os.walk(base):
        current = Path(dirpath)
        if (current / "versions").exists():
            artifact_directories.append(current)
            dirnames.clear()
    return artifact_directories

