def fetch_eval_case_from_eval_set(
    eval_set: EvalSet, eval_case_identifier: str
) -> Optional[EvalCase]:

  eval_case_to_find = None

  for eval_case in eval_set.eval_cases:
    if eval_case.eval_id == eval_case_identifier:
      eval_case_to_find = eval_case
      break

  return eval_case_to_find
